<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Aluno');
$id=$_SESSION['id_usuario'];$stmt=$conexao->prepare('SELECT u.*,m.rm,m.data_matricula,t.nome AS turma_nome,t.ano_letivo,t.periodo FROM usuario u LEFT JOIN matricula m ON m.id_aluno=u.id_usuario LEFT JOIN turma t ON t.id_turma=m.id_turma WHERE u.id_usuario=? AND u.perfil="Aluno" AND u.ativo=1');$stmt->bind_param('i',$id);$stmt->execute();$aluno=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$aluno){header('Location: inicio_aluno.php');exit();}
function atlas_escape($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function mostrar_aluno($campo,$valor){echo '<div class="field"><span class="field-label">'.atlas_escape($campo).'</span><div class="field-value">'.($valor===null||$valor===''?'<span class="not-informed">Não informado</span>':atlas_escape($valor)).'</div></div>';}
